import React, { useState } from 'react';
import { createAtividade } from '../api/ClienteApi';

const CreateAtividade = ({ clienteId, projetoId }) => {
  const [descricao, setDescricao] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const atividade = { descricao };
      await createAtividade(clienteId, projetoId, atividade);
      setDescricao('');
    } catch (error) {
      console.error('Erro ao criar atividade', error);
    }
  };

  return (
    <div>
      <h4>Criar Atividade para o Projeto {projetoId}</h4>
      <form onSubmit={handleSubmit}>
        <textarea
          value={descricao}
          onChange={(e) => setDescricao(e.target.value)}
          placeholder="Descrição da Atividade"
          required
        />
        <button type="submit">Criar Atividade</button>
      </form>
    </div>
  );
};

export default CreateAtividade;
